const signalLabels={pattern:'detayları ve bağlantıları fark etmen',people:'insanlarla birlikte düşünmen',maker:'bir şeyi deneyerek üretmen',empathy:'başkasının ihtiyacını sezmen',curiosity:'bilmediğin şeylerin peşinden gitmen',patience:'bir işi sabırla derinleştirmen'};
const guideIndex=professionCatalog.map(p=>{
  const salaryNumbers=(p.salary.match(/\d[\d.]*/g)||[]).map(x=>Number(x.replace(/\./g,''))).filter(Number.isFinite);
  p.salaryMin=salaryNumbers.length?Math.min(...salaryNumbers):0;p.salaryMax=salaryNumbers.length?Math.max(...salaryNumbers):0;
  const years=(p.educationLength.match(/\d+/)||[]).map(Number);p.educationBand=/kurs|sertifika|uygulama|deneyim/i.test(p.educationLength)&&(!years.length||years[0]<=2)?'short':years[0]>=5?'long':years[0]>=3?'medium':'short';
  p.cityAvailability=p.cityAvailability||cityProfiles[p.category]||['İstanbul','Ankara','İzmir','Diğer şehirler'];
  p.specialties=p.specialties||[...new Set([...(p.tags||[]),p.category])].slice(0,4);
  p.relatedIds=(p.similar||[]).map(name=>professionCatalog.find(other=>other.name===name)?.id).filter(Boolean);
  const officialSources=[{label:'TÜİK Kazanç Yapısı İstatistikleri',url:'https://veriportali.tuik.gov.tr/Bulten/Index?p=Kazanc-Yapisi-Istatistikleri-2023-53700'},{label:'YÖK Meslek Atlası',url:'https://yokatlas.yok.gov.tr/meslek-lisans.php'}];
  p.sources=[...(p.sources||[]),...officialSources.filter(source=>!(p.sources||[]).some(existing=>existing.url===source.url))];
  return {text:`${p.name} ${p.desc} ${(p.tags||[]).join(' ')} ${(p.specialties||[]).join(' ')}`.toLocaleLowerCase('tr'),profession:p};
});
const homeView=document.querySelector('main'); const setupView=$('[data-setup]'); const quizView=$('[data-quiz]'); const resultView=$('[data-result]'); const modal=$('[data-profession-modal]'); const comparisonModal=$('[data-comparison-modal]'); let current=0; let selected=null; let questionCount=12; let activeQuestions=questions.slice(0,12); let answers=[]; let lastMatches=[]; let selectedDetail=null; let comparison=[];
const storageKeys={progress:'yolunu-bul-progress',result:'yolunu-bul-result',favorites:'yolunu-bul-favorites',comparison:'yolunu-bul-comparison'};
function show(view){homeView.hidden=view!=='home'; document.querySelector('.site-header').hidden=view!=='home'; setupView.hidden=view!=='setup'; quizView.hidden=view!=='quiz'; resultView.hidden=view!=='result'; document.body.classList.toggle('quiz-active',view==='quiz');document.body.classList.toggle('result-active',view==='result');document.body.classList.toggle('setup-active',view==='setup');window.scrollTo({top:0,behavior:'instant'});}
function saveProgress(){localStorage.setItem(storageKeys.progress,JSON.stringify({questionCount,current,answers}));}
function clearProgress(){localStorage.removeItem(storageKeys.progress);}
function updateResume(){const saved=JSON.parse(localStorage.getItem(storageKeys.progress)||'null');const button=$('[data-resume]');if(saved&&saved.current<saved.questionCount){button.hidden=false;button.textContent=`${saved.current+1}. sorudan devam et`;button.dataset.saved='true'}else button.hidden=true;}
function restoreProgress(){const saved=JSON.parse(localStorage.getItem(storageKeys.progress)||'null');if(!saved)return;questionCount=saved.questionCount;activeQuestions=questions.slice(0,questionCount);current=Math.min(saved.current,activeQuestions.length-1);answers=Array.isArray(saved.answers)?saved.answers:[];show('quiz');renderQuestion();toast('Kaldığın yerden devam ediyorsun.');}
function renderQuestion(){const q=activeQuestions[current];selected=answers[current]??null;$('[data-counter]').textContent=`${String(current+1).padStart(2,'0')} / ${activeQuestions.length}`;$('[data-progress]').style.width=`${((current+1)/activeQuestions.length)*100}%`;$('[data-theme]').textContent=q.theme;$('[data-signal]').textContent=q.signal;$('[data-question]').textContent=q.question;$('[data-helper]').textContent=q.helper;$('[data-choices]').innerHTML=q.choices.map((c,i)=>`<button class="choice ${selected===i?'selected':''}" data-choice="${i}"><span class="choice-icon">${c[0]}</span><span class="choice-title">${c[1]}</span><span class="choice-copy">${c[2]}</span><span class="choice-check">✓</span></button>`).join('');$$('[data-choice]').forEach(btn=>btn.addEventListener('click',()=>{selected=Number(btn.dataset.choice);answers[current]=selected;saveProgress();$$('[data-choice]').forEach(x=>x.classList.toggle('selected',x===btn));$('[data-next]').disabled=false}));$('[data-next]').disabled=selected===null;$('[data-back]').disabled=current===0;}
function start(){show('setup');updateResume();}
function beginQuiz(){questionCount=Number(document.querySelector('.duration-option.selected')?.dataset.count||12);activeQuestions=questions.slice(0,questionCount);current=0;answers=[];saveProgress();show('quiz');renderQuestion();}
function signalScores(){const scores={pattern:0,people:0,maker:0,empathy:0,curiosity:0,patience:0};answers.forEach((answer,index)=>{if(answer===null||answer===undefined)return;const signal=activeQuestions[index]?.choices[answer]?.[3];if(signal)scores[signal]++});return scores;}
function matchLevel(score){return score>=6?'Çok güçlü eşleşme':score>=4?'Güçlü eşleşme':'Keşfetmeye değer';}
function renderResult(){const scores=signalScores();const topSignals=Object.entries(scores).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>x[0]);lastMatches=professionCatalog.map(p=>({...p,score:p.signals.reduce((sum,s)=>sum+(topSignals.includes(s)?2:0),0)})).sort((a,b)=>b.score-a.score).slice(0,4);const enough=answers.filter(a=>a!==null&&a!==undefined).length>=Math.max(4,Math.round(activeQuestions.length*.45));const resultCopy=enough?'Cevaplarında tekrar eden eğilimler, bağlantıları ve sistemleri okumaya yatkın olduğunu söylüyor.':'Bu bir ön değerlendirme: daha fazla cevap verdiğinde eşleşmelerin daha da netleşecek.';$('.result-lede').textContent=resultCopy;$('.result-content .eyebrow').textContent=enough?'CEVAPLARINDAN ÇIKAN İLK ÇİZGİ':'ÖN DEĞERLENDİRME';$('[data-result-professions]').innerHTML=lastMatches.map((p,i)=>`<div class="profession-result"><div class="profession-head"><b>${p.name}</b><span>${matchLevel(p.score)}</span></div><p>${p.why}</p><div class="profession-meta"><span><small>EĞİTİM</small>${p.education}</span><span><small>MAAŞ</small>${p.salary}</span><span><small>ZORLUK</small>${p.difficulty}</span><span><small>ORTAM</small>${p.environment}</span><span><small>İLK ADIM</small>${p.firstStep}</span></div><div class="result-card-actions"><button class="detail-link" data-open-profession="${p.id}">Detayları gör ↗</button><button class="favorite-link" data-favorite="${p.id}">${isFavorite(p.id)?'★':'☆'} Favori</button></div></div>`).join('');localStorage.setItem(storageKeys.result,JSON.stringify({matches:lastMatches,answers,questionCount,createdAt:new Date().toISOString()}));bindDynamicActions();}
function next(){if(selected===null)return;if(current<activeQuestions.length-1){current++;saveProgress();renderQuestion()}else{renderResult();clearProgress();show('result');updateResume()}}
function back(){if(current>0){current--;saveProgress();renderQuestion()}}
function toast(message){const node=$('[data-toast]');node.textContent=message;node.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>node.classList.remove('visible'),2800)}
function isFavorite(id){return JSON.parse(localStorage.getItem(storageKeys.favorites)||'[]').includes(id)}
function toggleFavorite(id){const items=JSON.parse(localStorage.getItem(storageKeys.favorites)||'[]');const next=items.includes(id)?items.filter(x=>x!==id):[...items,id];localStorage.setItem(storageKeys.favorites,JSON.stringify(next));return next.includes(id)}
function addToComparison(id){if(comparison.includes(id)){toast('Bu meslek zaten karşılaştırmada.');return}if(comparison.length>=3){toast('En fazla 3 mesleği karşılaştırabilirsin.');return}comparison=[...comparison,id];localStorage.setItem(storageKeys.comparison,JSON.stringify(comparison));renderComparisonBar();renderGuide();toast('Meslek karşılaştırmaya eklendi.')}
function removeFromComparison(id){comparison=comparison.filter(x=>x!==id);localStorage.setItem(storageKeys.comparison,JSON.stringify(comparison));renderComparisonBar();renderGuide();}
function clearComparison(){comparison=[];localStorage.removeItem(storageKeys.comparison);renderComparisonBar();renderGuide();closeComparison();toast('Karşılaştırma temizlendi.')}
function renderComparisonBar(){const bar=$('[data-comparison-bar]');const button=$('[data-open-comparison]');bar.hidden=comparison.length===0;$('[data-comparison-label]').textContent=`${comparison.length} / 3 meslek seçildi`;$('[data-comparison-chips]').innerHTML=comparison.map(id=>{const p=professionCatalog.find(x=>x.id===id);return p?`<button class="comparison-chip" data-remove-comparison="${p.id}">${p.name}<span>×</span></button>`:''}).join('');button.disabled=comparison.length<2;$$('[data-remove-comparison]').forEach(x=>x.addEventListener('click',()=>removeFromComparison(x.dataset.removeComparison)));}
function renderComparisonView(){const selected=comparison.map(id=>professionCatalog.find(p=>p.id===id)).filter(Boolean);const rows=[['MESLEK ÖZETİ','desc'],['EĞİTİM SÜRESİ','educationLength'],['ÜNİVERSİTE','university'],['YAKLAŞIK AYLIK MAAŞ','salary'],['TALEP','demand'],['ÇALIŞMA ORTAMI','environment'],['UZAKTAN ÇALIŞMA','remote'],['ZORLUK','difficulty'],['İŞE GİRİŞ','finding'],['İLK KÜÇÜK DENEME','firstStep']];$('[data-comparison-table]').innerHTML=`<div class="comparison-row comparison-head"><span></span>${selected.map(p=>`<div><span class="guide-icon">${p.icon}</span><strong>${p.name}</strong><button data-remove-comparison="${p.id}">Çıkar</button></div>`).join('')}</div>`+rows.map(([label,key])=>`<div class="comparison-row"><small>${label}</small>${selected.map(p=>`<div>${key==='university'?(p.university?'Üniversite gerekli veya avantajlı':'Üniversite şart değil; uygulamalı deneyim önemli'):p[key]||'Veri bulunamadı'}</div>`).join('')}</div>`).join('');$$('[data-remove-comparison]').forEach(x=>x.addEventListener('click',()=>{removeFromComparison(x.dataset.removeComparison);if(comparison.length<2)closeComparison();else renderComparisonView()}));}
function openComparison(){if(comparison.length<2){toast('Karşılaştırmak için en az 2 meslek seç.');return}renderComparisonView();comparisonModal.hidden=false;document.body.classList.add('modal-open')}
function closeComparison(){comparisonModal.hidden=true;document.body.classList.remove('modal-open')}
function openProfession(id){const p=professionCatalog.find(x=>x.id===id);if(!p)return;selectedDetail=p;$('[data-detail-category]').textContent=`${p.category} · ${p.icon}`;$('[data-detail-name]').textContent=p.name;$('[data-detail-desc]').textContent=p.desc;$('[data-detail-why]').textContent=p.why;$('[data-detail-daily]').textContent=p.daily;$('[data-detail-challenge]').textContent=p.challenge;$('[data-detail-first]').textContent=p.firstStep;$('[data-detail-similar]').textContent=p.similar.join(' · ');$('[data-detail-updated]').textContent=`Son güncelleme: ${p.updated}`;$('[data-detail-sources]').innerHTML=p.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noreferrer">${s.label}</a>`).join('<br>');$('[data-detail-meta]').innerHTML=[['EĞİTİM',p.education],['MAAŞ',p.salary],['TALEP',p.demand],['ÇALIŞMA ORTAMI',p.environment],['UZAKTAN',p.remote]].map(x=>`<div><small>${x[0]}</small><span>${x[1]}</span></div>`).join('');$('[data-favorite-detail]').textContent=isFavorite(p.id)?'★ Favorilerden çıkar':'☆ Favorilere ekle';$('[data-compare-detail]').textContent=comparison.includes(p.id)?'✓ Karşılaştırmada':'＋ Karşılaştırmaya ekle';modal.hidden=false;document.body.classList.add('modal-open');}
function bindDynamicActions(){$$('[data-open-profession]').forEach(x=>x.addEventListener('click',()=>openProfession(x.dataset.openProfession)));$$('[data-favorite]').forEach(x=>x.addEventListener('click',()=>{const active=toggleFavorite(x.dataset.favorite);x.textContent=`${active?'★':'☆'} Favori`;toast(active?'Meslek favorilere eklendi.':'Favorilerden çıkarıldı.')}));}
function closeModal(){modal.hidden=true;document.body.classList.remove('modal-open');selectedDetail=null;}
function renderGuide(){const categories=[...new Set(professionCatalog.map(p=>p.category))].sort((a,b)=>a.localeCompare(b,'tr'));$('[data-profession-category]').innerHTML='<option value="all">Tüm kategoriler</option>'+categories.map(c=>`<option value="${c}">${c}</option>`).join('');const draw=()=>{const search=$('[data-profession-search]').value.toLocaleLowerCase('tr');const category=$('[data-profession-category]').value;const demand=$('[data-profession-demand]').value;const education=$('[data-profession-education]').value;const remote=$('[data-profession-remote]').value;const difficulty=$('[data-profession-difficulty]').value;const matches=professionCatalog.filter(p=>(!search||`${p.name} ${p.desc} ${p.tags.join(' ')}`.toLocaleLowerCase('tr').includes(search))&&(category==='all'||p.category===category)&&(demand==='all'||p.demand===demand)&&(education==='all'||(education==='university'?p.university:!p.university))&&(remote==='all'||p.remote===remote)&&(difficulty==='all'||p.difficulty===difficulty));$('[data-profession-grid]').innerHTML=matches.length?matches.map(p=>`<article class="guide-card"><div class="guide-card-top"><span class="guide-icon">${p.icon}</span><span class="note-kicker">${p.category}</span></div><h3>${p.name}</h3><p>${p.desc}</p><div class="guide-stats"><span><small>TALEP</small>${p.demand}</span><span><small>MAAŞ</small>${p.salary}</span><span><small>UZAKTAN</small>${p.remote}</span></div><button class="detail-link" data-open-guide="${p.id}">Detayları gör ↗</button></article>`).join(''):'<div class="empty-guide"><span>⌁</span><h3>Bu aralıkta bir şey bulamadık.</h3><p>Arama kelimesini veya filtreleri değiştirip tekrar bak.</p><button class="compare-link" data-clear-filters>Filtreleri temizle</button></div>';$('[data-guide-count]').textContent=`${matches.length} meslek`;$$('[data-open-guide]').forEach(x=>x.addEventListener('click',()=>openProfession(x.dataset.openGuide)));decorateGuideCards();};['[data-profession-search]','[data-profession-category]','[data-profession-demand]','[data-profession-education]','[data-profession-remote]','[data-profession-difficulty]'].forEach(s=>$(s).addEventListener('input',draw));draw();}
function decorateGuideCards(){const cards=$$('[data-open-guide]');cards.forEach(button=>{const card=button.closest('.guide-card');if(!card||card.querySelector('[data-compare-guide]'))return;const id=button.dataset.openGuide;const compare=document.createElement('button');compare.className='compare-link';compare.dataset.compareGuide=id;compare.textContent=comparison.includes(id)?'✓ Karşılaştırmada':'＋ Karşılaştırmaya ekle';compare.disabled=!comparison.includes(id)&&comparison.length>=3;compare.addEventListener('click',()=>addToComparison(id));card.append(compare)});}
function clearGuideFilters(){$('[data-profession-search]').value='';['data-profession-category','data-profession-demand','data-profession-education','data-profession-education-length','data-profession-salary','data-profession-city','data-profession-remote','data-profession-difficulty'].forEach(attr=>{const select=$(`[${attr}]`);if(select)select.value='all'});renderGuide();}
function salaryMatches(p,band){if(band==='all')return true;if(band==='under-40')return p.salaryMin<40000;if(band==='40-80')return p.salaryMax>=40000&&p.salaryMin<=80000;if(band==='80-150')return p.salaryMax>=80000&&p.salaryMin<=150000;if(band==='over-150')return p.salaryMax>=150000;return true}
function explainMatch(p,topSignals){const matched=p.signals.filter(signal=>topSignals.includes(signal)).slice(0,3);const readable=matched.map(signal=>signalLabels[signal]).filter(Boolean);const evidence=answers.map((answer,index)=>answer===null||answer===undefined?'':activeQuestions[index]?.choices[answer]?.[1]).filter(Boolean).slice(0,2);const evidenceText=evidence.length?` Son cevaplarında “${evidence.join('” ve “')}” gibi seçimler de bu çizgiyi destekliyor.`:'';return `${readable.length?readable.join(', '):'cevaplarında tekrar eden çalışma reflekslerin'} nedeniyle öne çıktı. ${p.why}${evidenceText}`}
function renderResult(){const scores=signalScores();const topSignals=Object.entries(scores).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>x[0]);lastMatches=professionCatalog.map(p=>({...p,score:p.signals.reduce((sum,s)=>sum+(topSignals.includes(s)?2:0),0)})).sort((a,b)=>b.score-a.score).slice(0,4);const enough=answers.filter(a=>a!==null&&a!==undefined).length>=Math.max(4,Math.round(activeQuestions.length*.45));$('.result-lede').textContent=enough?'Cevaplarının içindeki tekrarları, seçtiğin küçük ipuçlarını ve çalışma reflekslerini birlikte okuyarak ilk yönleri çıkardık.':'Bu bir ön değerlendirme: daha fazla cevap verdiğinde eşleşmelerin ve açıklamaların daha da netleşecek.';$('.result-content .eyebrow').textContent=enough?'CEVAPLARINDAN ÇIKAN İLK ÇİZGİ':'ÖN DEĞERLENDİRME';$('[data-result-professions]').innerHTML=lastMatches.map(p=>`<div class="profession-result"><div class="profession-head"><b>${p.name}</b><span>${matchLevel(p.score)}</span></div><p>${explainMatch(p,topSignals)}</p><div class="profession-meta"><span><small>EĞİTİM</small>${p.education}</span><span><small>MAAŞ</small>${p.salary}</span><span><small>ZORLUK</small>${p.difficulty}</span><span><small>ORTAM</small>${p.environment}</span><span><small>İLK ADIM</small>${p.firstStep}</span></div><div class="result-card-actions"><button class="detail-link" data-open-profession="${p.id}">Detayları gör ↗</button><button class="favorite-link" data-favorite="${p.id}">${isFavorite(p.id)?'★':'☆'} Favori</button></div></div>`).join('');localStorage.setItem(storageKeys.result,JSON.stringify({matches:lastMatches,answers,questionCount,createdAt:new Date().toISOString(),topSignals}));bindDynamicActions();}
function renderGuide(){const categories=[...new Set(professionCatalog.map(p=>p.category))].sort((a,b)=>a.localeCompare(b,'tr'));const categorySelect=$('[data-profession-category]');const previousCategory=categorySelect.value;categorySelect.innerHTML='<option value="all">Tüm kategoriler</option>'+categories.map(c=>`<option value="${c}">${c}</option>`).join('');categorySelect.value=categories.includes(previousCategory)?previousCategory:'all';const draw=()=>{const search=$('[data-profession-search]').value.toLocaleLowerCase('tr').trim();const category=categorySelect.value;const demand=$('[data-profession-demand]').value;const education=$('[data-profession-education]').value;const educationLength=$('[data-profession-education-length]').value;const salary=$('[data-profession-salary]').value;const city=$('[data-profession-city]').value;const remote=$('[data-profession-remote]').value;const difficulty=$('[data-profession-difficulty]').value;const matches=guideIndex.filter(({text,profession})=>!search||text.includes(search)).map(({profession})=>profession).filter(profession=>(category==='all'||profession.category===category)&&(demand==='all'||profession.demand===demand)&&(education==='all'||(education==='university'?profession.university:!profession.university))&&(educationLength==='all'||profession.educationBand===educationLength)&&salaryMatches(profession,salary)&&(city==='all'||profession.cityAvailability.includes(city))&&(remote==='all'||profession.remote===remote)&&(difficulty==='all'||profession.difficulty===difficulty));$('[data-profession-grid]').innerHTML=matches.length?matches.map(p=>`<article class="guide-card"><div class="guide-card-top"><span class="guide-icon">${p.icon}</span><span class="note-kicker">${p.category}</span></div><h3>${p.name}</h3><p>${p.desc}</p><div class="guide-specialties">${p.specialties.slice(0,3).map(tag=>`<span>${tag}</span>`).join('')}</div><div class="guide-stats"><span><small>TALEP</small>${p.demand}</span><span><small>MAAŞ</small>Yaklaşık aralık</span><span><small>UZAKTAN</small>${p.remote}</span></div><button class="detail-link" data-open-guide="${p.id}">Detayları gör ↗</button></article>`).join(''):'<div class="empty-guide"><span>⌁</span><h3>Bu aralıkta bir şey bulamadık.</h3><p>Arama kelimesini veya filtreleri değiştirip tekrar bak.</p><button class="compare-link" data-clear-filters>Filtreleri temizle</button></div>';$('[data-guide-count]').textContent=`${matches.length} meslek`;$$('[data-open-guide]').forEach(x=>x.addEventListener('click',()=>openProfession(x.dataset.openGuide)));decorateGuideCards();};window.guideDraw=draw;const controls=['[data-profession-search]','[data-profession-category]','[data-profession-demand]','[data-profession-education]','[data-profession-education-length]','[data-profession-salary]','[data-profession-city]','[data-profession-remote]','[data-profession-difficulty]'];controls.forEach(selector=>{const control=$(selector);if(control.dataset.guideBound)return;control.dataset.guideBound='true';control.addEventListener(control.tagName==='INPUT'?'input':'change',()=>{clearTimeout(window.guideTimer);window.guideTimer=setTimeout(draw,control.tagName==='INPUT'?120:0)})});draw();}
function openProfession(id){const p=professionCatalog.find(x=>x.id===id);if(!p)return;selectedDetail=p;$('[data-detail-category]').textContent=`${p.category} · ${p.icon}`;$('[data-detail-name]').textContent=p.name;$('[data-detail-desc]').textContent=p.desc;$('[data-detail-why]').textContent=p.why;$('[data-detail-daily]').textContent=p.daily;$('[data-detail-challenge]').textContent=p.challenge;$('[data-detail-first]').textContent=p.firstStep;$('[data-detail-similar]').innerHTML=(p.relatedIds||[]).map(relatedId=>{const related=professionCatalog.find(x=>x.id===relatedId);return related?`<button class="similar-profession" data-open-similar="${related.id}">${related.name} ↗</button>`:''}).join('')||'<span>Benzer meslek verisi bulunamadı.</span>';$('[data-detail-specialties]').innerHTML=`<span class="note-kicker">ALT UZMANLIKLAR</span><div>${p.specialties.map(tag=>`<span>${tag}</span>`).join('')}</div><small>Yaygın merkezler: ${p.cityAvailability.join(' · ')}</small>`;$('[data-detail-updated]').textContent=`Son güncelleme: ${p.updated} · Maaş ve talep şehir, deneyim, sektör ve kaynak dönemine göre değişir.`;$('[data-detail-sources]').innerHTML=p.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noreferrer">${s.label}</a>`).join('<br>');$('[data-detail-meta]').innerHTML=[['EĞİTİM',p.education],['EĞİTİM SÜRESİ',p.educationLength],['MAAŞ',p.salary],['TALEP',p.demand],['ÇALIŞMA ORTAMI',p.environment],['UZAKTAN',p.remote]].map(x=>`<div><small>${x[0]}</small><span>${x[1]}</span></div>`).join('');$('[data-favorite-detail]').textContent=isFavorite(p.id)?'★ Favorilerden çıkar':'☆ Favorilere ekle';$('[data-compare-detail]').textContent=comparison.includes(p.id)?'✓ Karşılaştırmada':'＋ Karşılaştırmaya ekle';$$('[data-open-similar]').forEach(button=>button.addEventListener('click',()=>openProfession(button.dataset.openSimilar)));modal.hidden=false;document.body.classList.add('modal-open');}
function shortSalary(p){if(!p.salaryMin&&!p.salaryMax)return'Veri bulunamadı';const compact=value=>`₺${Math.round(value/1000)}K`;return p.salaryMin&&p.salaryMax&&p.salaryMin!==p.salaryMax?`${compact(p.salaryMin)}–${compact(p.salaryMax)}`:compact(p.salaryMax||p.salaryMin)}
function setupFilterDrawer(){const toolbar=$('.guide-toolbar');if(toolbar.dataset.filterDrawerReady)return;toolbar.dataset.filterDrawerReady='true';const advanced=['[data-profession-education-length]','[data-profession-salary]','[data-profession-city]','[data-profession-remote]','[data-profession-difficulty]'].map(selector=>$(selector));const drawer=document.createElement('details');drawer.className='filter-drawer';drawer.innerHTML='<summary><span>İleri filtreler</span><small>eğitim, maaş, şehir, uzaktan, zorluk</small><b>＋</b></summary><div class="filter-drawer-panel"></div>';advanced.forEach(select=>drawer.querySelector('.filter-drawer-panel').append(select));toolbar.append(drawer)}
function renderGuideCards(matches){const groups=new Map();matches.forEach(p=>{if(!groups.has(p.category))groups.set(p.category,[]);groups.get(p.category).push(p)});$('[data-profession-grid]').innerHTML=matches.length?[...groups].map(([category,items])=>`<section class="guide-category-group"><header><span class="note-kicker">${category}</span><strong>${items.length} yön</strong></header><div class="guide-grid">${items.map(p=>`<article class="guide-card"><div class="guide-card-top"><span class="guide-icon">${p.icon}</span><span class="note-kicker">${p.category}</span></div><h3>${p.name}</h3><p>${p.desc}</p><div class="guide-specialties">${p.specialties.slice(0,3).map(tag=>`<span>${tag}</span>`).join('')}</div><div class="guide-stats"><span><small>TALEP</small>${p.demand}</span><span><small>MAAŞ</small>${shortSalary(p)}<i>yaklaşık</i></span><span><small>UZAKTAN</small>${p.remote}</span></div><button class="detail-link" data-open-guide="${p.id}">Detayları gör ↗</button></article>`).join('')}</div></section>`).join(''):'<div class="empty-guide"><span>⌁</span><h3>Bu aralıkta bir şey bulamadık.</h3><p>Arama kelimesini veya filtreleri değiştirip tekrar bak.</p><button class="compare-link" data-clear-filters>Filtreleri temizle</button></div>';}
function decorateGuideCards(){const buttons=$$('[data-open-guide]');buttons.forEach(button=>{const card=button.closest('.guide-card');if(!card||card.querySelector('[data-compare-guide]'))return;const id=button.dataset.openGuide;const compare=document.createElement('button');compare.className=`compare-link ${comparison.includes(id)?'is-selected':''}`;compare.dataset.compareGuide=id;compare.textContent=comparison.includes(id)?'✓ Karşılaştırmada':'＋ Karşılaştırmaya ekle';compare.disabled=!comparison.includes(id)&&comparison.length>=3;compare.addEventListener('click',()=>addToComparison(id));card.append(compare)})}
function renderGuide(){setupFilterDrawer();const categories=[...new Set(professionCatalog.map(p=>p.category))].sort((a,b)=>a.localeCompare(b,'tr'));const categorySelect=$('[data-profession-category]');const previousCategory=categorySelect.value;categorySelect.innerHTML='<option value="all">Tüm kategoriler</option>'+categories.map(c=>`<option value="${c}">${c}</option>`).join('');categorySelect.value=categories.includes(previousCategory)?previousCategory:'all';const draw=()=>{const search=$('[data-profession-search]').value.toLocaleLowerCase('tr').trim();const category=categorySelect.value;const demand=$('[data-profession-demand]').value;const education=$('[data-profession-education]').value;const educationLength=$('[data-profession-education-length]').value;const salary=$('[data-profession-salary]').value;const city=$('[data-profession-city]').value;const remote=$('[data-profession-remote]').value;const difficulty=$('[data-profession-difficulty]').value;const matches=guideIndex.filter(({text,profession})=>!search||text.includes(search)).map(({profession})=>profession).filter(profession=>(category==='all'||profession.category===category)&&(demand==='all'||profession.demand===demand)&&(education==='all'||(education==='university'?profession.university:!profession.university))&&(educationLength==='all'||profession.educationBand===educationLength)&&salaryMatches(profession,salary)&&(city==='all'||profession.cityAvailability.includes(city))&&(remote==='all'||profession.remote===remote)&&(difficulty==='all'||profession.difficulty===difficulty));renderGuideCards(matches);$('[data-guide-count]').textContent=`${matches.length} meslek`;$$('[data-open-guide]').forEach(x=>x.addEventListener('click',()=>openProfession(x.dataset.openGuide)));decorateGuideCards()};window.guideDraw=draw;const controls=['[data-profession-search]','[data-profession-category]','[data-profession-demand]','[data-profession-education]','[data-profession-education-length]','[data-profession-salary]','[data-profession-city]','[data-profession-remote]','[data-profession-difficulty]'];controls.forEach(selector=>{const control=$(selector);if(control.dataset.guideBound)return;control.dataset.guideBound='true';control.addEventListener(control.tagName==='INPUT'?'input':'change',()=>{clearTimeout(window.guideTimer);window.guideTimer=setTimeout(draw,control.tagName==='INPUT'?120:0)})});draw()}
const departmentCatalog=window.departmentCatalog||[];let selectedDepartment=null;
function departmentDurationBand(department){if(department.degreeLength.includes('2'))return'short';if(department.degreeLength.includes('5')||department.degreeLength.includes('6'))return'long';return'medium'}
function renderDepartments(){const fieldSelect=$('[data-department-field]');if(!fieldSelect)return;const fields=[...new Set(departmentCatalog.map(d=>d.field))].sort((a,b)=>a.localeCompare(b,'tr'));fieldSelect.innerHTML='<option value="all">Tüm alanlar</option>'+fields.map(field=>`<option value="${field}">${field}</option>`).join('');const draw=()=>{const search=$('[data-department-search]').value.toLocaleLowerCase('tr').trim();const field=fieldSelect.value;const duration=$('[data-department-duration]').value;const university=$('[data-department-university]').value;const matches=departmentCatalog.filter(d=>{const text=`${d.name} ${d.field} ${d.desc} ${d.skills.join(' ')} ${d.careers.join(' ')}`.toLocaleLowerCase('tr');return(!search||text.includes(search))&&(field==='all'||d.field===field)&&(duration==='all'||departmentDurationBand(d)===duration)&&(university==='all'||(university==='yes'?d.university:!d.university))});$('[data-department-count]').textContent=`${matches.length} bölüm`; $('[data-department-grid]').innerHTML=matches.length?matches.map(d=>`<article class="department-card"><div class="department-card-top"><span class="department-field">${d.field}</span><span class="department-length">${d.degreeLength}</span></div><h3>${d.name}</h3><p>${d.desc}</p><div class="department-tags">${d.skills.slice(0,3).map(skill=>`<span>${skill}</span>`).join('')}</div><div class="department-card-meta"><span>${d.studyType}</span><span>${d.university?'Üniversite yolu':'Alternatif yollar da var'}</span></div><div class="department-card-actions"><button class="department-open" data-open-department="${d.id}">Bölüm detayını gör ↗</button></div></article>`).join(''):'<div class="department-empty"><h3>Bu filtrelerle bölüm bulamadık.</h3><p>Alanı veya eğitim süresini değiştirip yeniden bak.</p></div>';$$('[data-open-department]').forEach(button=>button.addEventListener('click',()=>openDepartment(button.dataset.openDepartment)))};const controls=['[data-department-search]','[data-department-field]','[data-department-duration]','[data-department-university]'];controls.forEach(selector=>{const control=$(selector);if(control.dataset.departmentBound)return;control.dataset.departmentBound='true';control.addEventListener(control.tagName==='INPUT'?'input':'change',()=>{clearTimeout(window.departmentTimer);window.departmentTimer=setTimeout(draw,control.tagName==='INPUT'?120:0)})});window.departmentDraw=draw;draw()}
function openDepartment(id){const d=departmentCatalog.find(item=>item.id===id);if(!d)return;selectedDepartment=d;$('[data-department-detail-field]').textContent=`${d.field} · ${d.studyType}`;$('[data-department-name]').textContent=d.name;$('[data-department-desc]').textContent=d.desc;$('[data-department-character]').textContent=d.character;$('[data-department-fit]').textContent=d.fit;$('[data-department-challenge]').textContent=d.challenge;$('[data-department-first]').textContent=d.firstStep;$('[data-department-careers]').innerHTML=d.careers.map(career=>`<span>${career}</span>`).join('');$('[data-department-meta]').innerHTML=[['EĞİTİM SÜRESİ',d.degreeLength],['ALAN',d.field],['EĞİTİM TÜRÜ',d.studyType],['ÜNİVERSİTE',d.university?'Gerekli / avantajlı':'Tek yol değil']].map(x=>`<div><small>${x[0]}</small><span>${x[1]}</span></div>`).join('');$('[data-department-source]').href=d.source;$('[data-department-updated]').textContent=`Son güncelleme: ${d.updated} · Üniversite, şehir ve programa göre dersler değişebilir.`;$('[data-department-modal]').hidden=false;document.body.classList.add('modal-open')}
function closeDepartment(){const departmentModal=$('[data-department-modal]');if(!departmentModal)return;departmentModal.hidden=true;document.body.classList.remove('modal-open');selectedDepartment=null}
